Translate("frFR", "overlord-mok-morokk", {
	title = "Suzerain Mok'Morokk",
	subtitle = "Suzerain des Cognepierres",
	found = "Mur-de-Fougères",
	hint = [=[Inclinez-vous devant le suzerain des Cognepierres à Mur-de-Fougères.]=],
	allegiance = "Ogres Cognepierres · Horde",
	aliases = { "Mok'Morokk" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le suzerain Mok'Morokk gouverne les {red:stonemaul-ogres}ogres Cognepierres{/red} depuis {link:brackenwall-village}Mur-de-Fougères{/link}. {link:rexxar}Rexxar{/link} fit de lui un suzerain, et Mok'Morokk ne laisse jamais personne l'oublier. Quand des dragons noirs incendièrent le {link:stonemaul-ruins}village des Cognepierres{/link} dans le sud, il mena son peuple vers le nord, dans les roseaux. Il appelle cela de la sagesse. Beaucoup de ses ogres appellent cela une fuite.]=],
		},
		{
			title = "Importance",
			text = [=[Mok'Morokk montre ce que le pouvoir peut faire d'un chef que nul ne surveille. Il était fort tant que {link:rexxar}Rexxar{/link} menait le clan. Après le départ de Rexxar, il se mit à exiger qu'on le serve au lieu de servir, et son peuple commença à se retourner contre lui.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il mena les Cognepierres hors de leur ancien village quand les dragons noirs arrivèrent.
• Il renvoya d'autres que lui dans les ruines chercher le grog, le tabac à priser et le coffre-fort qu'il avait laissés.
• Il refusa de prendre les armes contre la couvée d'{link:onyxia}Onyxia{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Les affaires du suzerain",
			hint = "Récupérez ce que le suzerain a laissé dans le sud.",
			text = [=[Mok'Morokk quitta son foyer si précipitamment qu'il oublia les choses qu'il aimait le plus. Il ne retourna pas les chercher lui-même. Il était trop occupé à diriger, disait-il. D'autres descendirent donc vers le sud, dans le feu des {link:stonemaul-ruins}Ruines Cognepierres{/link} et de l'Antre des flammes, et rapportèrent son grog, son tabac à priser et son coffre à trésor.]=],
		},
		{
			title = "Le défi",
			hint = "Défiez le suzerain dans son propre village.",
			text = [=[{link:draz-zilb}Draz'Zilb{/link} avait décidé que le clan avait besoin d'un nouveau chef. Quand le suzerain fut défié à {link:brackenwall-village}Mur-de-Fougères{/link}, il rit et promit une raclée. Il perdit. Le puissant suzerain des Cognepierres s'enfuit de son propre village comme un enfant apeuré, et les ogres se mirent à parler de choisir un chef qui les ramènerait chez eux.]=],
		},
	},
	mentions = {
		{ text = "Overlord Mok'Morokk's Concern" },
		{ text = "The Brood of {link:onyxia}Onyxia{/link}" },
		{ text = "The Brood of {link:onyxia}Onyxia{/link}" },
		{ text = "Challenge Overlord Mok'Morokk" },
	},
	bonds = {
		{ id = "rexxar", name = "Rexxar", note = "fit de lui un suzerain" },
		{ id = "draz-zilb", name = "Draz'Zilb", note = "complota sa chute" },
		{ id = "tharg", name = "Tharg", note = "le blâme pour la fuite" },
	},
})

